/**
 * JsonUI Test Runner - Web Driver
 * The state bridge (app -> driver, spec §10.4): `window.__JSONUI_STATE__[screenId]`
 * holds `{ launchId, initialState: { applied, rejected } | null, data }` for each
 * screen showing, published by the generated hook (rjui's useJsonUITestBridge)
 * while NODE_ENV !== 'production'.
 *
 * Two readers: the receipt check after a launch that carried a payload
 * (waitForReceipt), and the default `state` provider (lookupState, whose path
 * rule and outcomes are specs/vectors/state-path.json).
 */

import type { Page } from 'playwright';

export interface InitialStateReceipt {
  applied: string[];
  rejected: { key: string; reason: string }[];
}

/** What the bridge holds for one screen (only `truncated` on an iOS overflow). */
export interface BridgeSnapshot {
  launchId?: string | null;
  initialState?: InitialStateReceipt | null;
  data?: Record<string, unknown>;
  truncated?: number;
}

/**
 * Read one screen's bridge. Null when the page has no bridge for it (the screen
 * is not showing, the build has the gate closed, or the page does not go
 * through the generated hook).
 */
export async function readBridge(page: Page, screenId: string): Promise<BridgeSnapshot | null> {
  const value = await page.evaluate((id) => {
    const all = (window as unknown as { __JSONUI_STATE__?: Record<string, unknown> }).__JSONUI_STATE__;
    if (!all || typeof all !== 'object') return null;
    const entry = all[id];
    return entry === undefined ? null : entry;
  }, screenId);
  return value && typeof value === 'object' ? (value as BridgeSnapshot) : null;
}

// MARK: - Path resolution (state-path.json, part 1)

export type PathResolution = { resolved: true; value: unknown } | { resolved: false };

const INDEX_SEGMENT = /^(0|[1-9][0-9]*)$/;

/**
 * Resolve a dot path in bridge data. On an object a segment is a key (digits
 * included); on an array a decimal segment without a leading zero is an index;
 * an empty segment, or a step into a string / number / boolean / null, does
 * not resolve. A key holding null resolves to null.
 */
export function resolveStatePath(data: unknown, path: string): PathResolution {
  let current: unknown = data;
  for (const segment of path.split('.')) {
    if (segment === '') return { resolved: false };
    if (Array.isArray(current)) {
      if (!INDEX_SEGMENT.test(segment)) return { resolved: false };
      const index = Number(segment);
      if (index >= current.length) return { resolved: false };
      current = current[index];
    } else if (current !== null && typeof current === 'object') {
      if (!Object.prototype.hasOwnProperty.call(current, segment)) return { resolved: false };
      current = (current as Record<string, unknown>)[segment];
    } else {
      return { resolved: false };
    }
  }
  return { resolved: true, value: current };
}

// MARK: - Bridge outcomes (state-path.json, part 2)

export type StateLookup =
  | { outcome: 'value'; value: unknown }
  | { outcome: 'unresolved' }
  /** No bridge, or one without data: keep waiting; `reason` explains it on timeout. */
  | { outcome: 'pending'; reason: string }
  /** iOS over 32 KB: fails at once. */
  | { outcome: 'truncated'; bytes: number };

export function lookupInBridge(bridge: BridgeSnapshot | null, path: string, screenId = '?'): StateLookup {
  if (bridge === null || bridge === undefined) {
    return {
      outcome: 'pending',
      reason:
        `no state bridge for screen '${screenId}' (window.__JSONUI_STATE__['${screenId}'] is absent: ` +
        'the screen is not showing, or the page was not built through the generated hook of a ' +
        'jsonui-cli with the test bridge, or NODE_ENV is production)'
    };
  }
  if (typeof bridge.truncated === 'number') {
    return { outcome: 'truncated', bytes: bridge.truncated };
  }
  if (!bridge.data || typeof bridge.data !== 'object') {
    return { outcome: 'pending', reason: `the state bridge for screen '${screenId}' has no data` };
  }
  const resolved = resolveStatePath(bridge.data, path);
  return resolved.resolved ? { outcome: 'value', value: resolved.value } : { outcome: 'unresolved' };
}

// MARK: - Receipt (spec §10.5)

/** The causes a missing receipt has, listed in its failure message. */
const NO_RECEIPT_CAUSES =
  '  - the app was generated by a jsonui-cli older than the one with the test bridge (rebuild with `jui build`)\n' +
  "  - a build with the gate closed (NODE_ENV === 'production')\n" +
  '  - a page that does not go through the generated hook (call useJsonUITestBridge in a hand-written page)\n' +
  "  - a screen id that does not match (the layout file's basename)";

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Wait for the screen's bridge to show the receipt of `launchId`, up to
 * `timeout` ms. Throws when none comes (no receipt), or when the receipt
 * rejects any key (each key and reason listed).
 */
export async function waitForReceipt(
  page: Page,
  screenId: string,
  launchId: string,
  timeout: number,
  pollMs = 100
): Promise<InitialStateReceipt> {
  const deadline = Date.now() + timeout;
  let seen = 'no bridge for the screen';
  for (;;) {
    const bridge = await readBridge(page, screenId);
    if (bridge && bridge.launchId === launchId && bridge.initialState) {
      const receipt = bridge.initialState;
      const rejected = Array.isArray(receipt.rejected) ? receipt.rejected : [];
      if (rejected.length > 0) {
        throw new Error(
          `initialState for screen '${screenId}' was rejected by the app:\n` +
          rejected.map(r => `  - ${r.key}: ${r.reason}`).join('\n')
        );
      }
      return { applied: Array.isArray(receipt.applied) ? receipt.applied : [], rejected: [] };
    }
    if (bridge) {
      seen = bridge.launchId === launchId
        ? 'a bridge for this launch without a receipt (initialState: null)'
        : `a bridge for another launch (launchId ${JSON.stringify(bridge.launchId ?? null)})`;
    }
    if (Date.now() >= deadline) break;
    await sleep(Math.min(pollMs, Math.max(0, deadline - Date.now())));
  }
  throw new Error(
    `initialState for screen '${screenId}': no receipt from the app within ${timeout}ms ` +
    `(launchId ${launchId}; last seen: ${seen}). Likely causes:\n${NO_RECEIPT_CAUSES}`
  );
}
